auto func (auto value){  
    bool hasAlpha = false;  
    for (char c : value) {  
        if (isalpha(c)) {  
            hasAlpha = true;  
            break;  
        }  
    }  
    return make_pair(hasAlpha, count_if(value.begin(), value.end(), ::isalpha)

auto func (auto value){  
    bool hasDigit = false;
    for (const auto& ch : value) {
        if (isdigit(ch)) {
            hasDigit = true;
            break;
        }
    }
    return hasDigit;
}

auto func (auto value){  
    for (char c : value) {  
        if (isdigit(c)) return true;  
    }  
    return false;  
}
